// Compiles a room-layout YAML string into a HL7 FHIR Questionnaire resource, validating it
// first against:
//   1. the design-time JSON Schema at data/form-schematics.schema.json (structural shape), and
//   2. the per-resource path shards in data/graphs.bundle.json (semantic FHIR path validity),
// both generated by tools/dictionary-builder.js + tools/build-graphs-bundle.js (run via
// `npm run build:kernel`) — bundled imports, since Workers has no filesystem to read from at
// request time. tools/build-system-forms.js (also part of build:kernel) imports this exact same
// function to precompile the system-forms catalog, so there is only one YAML→Questionnaire
// compiler used both at build time and request time.
import * as yaml from 'js-yaml';
import Ajv from 'ajv';
import ajvErrors from 'ajv-errors';
// The `with { type: 'json' }` import attribute is required by current Node's ESM loader for a
// plain JSON import (this module is now also run directly under Node by tools/build-system-
// forms.js, not just bundled by wrangler/esbuild for the Worker) — both esbuild and Node support
// the attribute, so this works in both places rather than needing two different import styles.
import metaSchema from '../../data/form-schematics.schema.json' with { type: 'json' };
import graphBundle from '../../data/graphs.bundle.json' with { type: 'json' };

// Initialize Ajv with error messaging modifiers. Ajv v8 reports errors as JSON Pointers by
// default, so no explicit `jsonPointers` option is needed (it was an Ajv v6-era flag).
const ajv = new Ajv({
    allErrors: true,
    meta: false,            // Tells Ajv not to check remote drafts
    strictSchema: false,    // Silences validation complaints about the $schema identifier
    validateSchema: false   // Instructs Ajv to skip full validation on the meta-schema itself
});
ajvErrors(ajv);
const validateStructure = ajv.compile(metaSchema);

/**
 * Maps your unified form components into official native FHIR Questionnaire item types
 */
function mapUiComponentToFhirType(uiComponent) {
    switch (uiComponent) {
        case 'NumericInput':
            return 'decimal';
        case 'Checkbox':
            return 'boolean';
        case 'DatePicker':
            return 'date';
        case 'Dropdown':
            return 'choice';
        case 'Autocomplete':
            return 'open-choice'; // Feature 2 & 4: Supports off-list entry/AJAX lookups
        case 'MultiSelect':
            return 'choice';
        case 'TextInput':
        case 'Hidden':
        default:
            return 'string';
    }
}

/**
 * Parses a room-layout YAML string, validates it structurally (JSON Schema) and semantically
 * (each field.path must exist in its resource's graph shard), then returns the resulting FHIR
 * Questionnaire.
 * @param {string} yamlSource - The source room-layout YAML text.
 * @returns {{ success: true, questionnaire: object } | { success: false, errors: string[] }}
 */
export function compileYamlToQuestionnaire(yamlSource) {
    // 1. Read and convert the user-authored YAML source into data objects
    let yamlDoc;
    try {
        yamlDoc = yaml.load(yamlSource);
    } catch (e) {
        return { success: false, errors: [`[YAML Syntax Error] ${e.message}`] };
    }

    // 2. Phase 1 Verification: Syntactic structural alignment via JSON Schema
    const isStructureValid = validateStructure(yamlDoc);
    const compilationErrors = [];

    if (!isStructureValid) {
        validateStructure.errors.forEach(err => {
            compilationErrors.push(`[Structural Error] Path '${err.instancePath}' ${err.message}`);
        });
    }

    // 3. Phase 2 Verification: Semantic context validation against master code constraints
    if (yamlDoc && Array.isArray(yamlDoc.composition)) {
        yamlDoc.composition.forEach((resourceBlock, blockIdx) => {
            const currentResource = resourceBlock.resourceType;
            const shardGraphNodes = graphBundle[currentResource.toLowerCase()];

            if (!shardGraphNodes) {
                compilationErrors.push(`[Composition Mismatch] Block[${blockIdx}] targets an un-indexed or restricted FHIR resource: '${currentResource}'`);
                return;
            }

            const allowedShardPaths = new Set(shardGraphNodes.map(node => node.path));

            if (Array.isArray(resourceBlock.fields)) {
                resourceBlock.fields.forEach((field) => {
                    // Audit each configured field path variable against the allowed shard set boundaries
                    if (!allowedShardPaths.has(field.path)) {
                        compilationErrors.push(`[Invalid FHIR Path] Block[${blockIdx}] targeting '${currentResource}' contains an unrecognized field path: '${field.path}'. Double check spelling or re-run dictionary builder.`);
                        return;
                    }

                    // Check A: Does the path explicitly match its structural category parent block?
                    if (!field.path.startsWith(`${currentResource}.`)) {
                        compilationErrors.push(
                            `[Composition Mismatch] Block[${blockIdx}] targeting '${currentResource}' contains an invalid field reference path: '${field.path}'.`
                        );
                    }

                    // Find the node to execute your vocabulary checks
                    const targetNode = shardGraphNodes.find(n => n.path === field.path);

                    // Native enum enforcement validation guard rule
                    if (targetNode && targetNode.primitiveType === 'enum' && field.uiComponent === 'Dropdown') {
                        if (!field.choices || field.choices.length === 0) {
                            compilationErrors.push(`[Missing Vocabulary Options] Path '${field.path}' requires choices defined in the YAML file to build the dropdown UI selector.`);
                        }
                    }
                });
            }
        });
    }

    // Process accumulated errors immediately
    if (compilationErrors.length > 0) {
        return { success: false, errors: compilationErrors };
    }

    // 4. Structure Generation Engine: Convert validated parameters into HL7 FHIR structures
    const fhirQuestionnaire = {
        resourceType: "Questionnaire",
        id: yamlDoc.formId,
        status: "active",
        title: yamlDoc.title || "Clinical Questionnaire",
        subjectType: [yamlDoc.composition[0]?.resourceType || "Patient"],
        // Native SDC Mapping Strategy: Instruct the HAPI Server to engage its default parsing workflow
        extension: [
            {
                url: "http://hl7.org",
                valueCode: "definition"
            }
        ],
        item: []
    };

    // Optional — tags a custom form as belonging to the Patient or Hospital journey so those
    // workflows can surface it themselves (see clinux-custom-forms-in-patient-hospital-journeys
    // memory note). A plain top-level property, same non-standard-but-established convention
    // this compiler already uses for id/title above rather than a proper FHIR extension.
    if (yamlDoc.journey) {
        fhirQuestionnaire.journey = yamlDoc.journey;
    }

    // Flatten composition configurations down into individual Questionnaire sections
    yamlDoc.composition.forEach(resourceBlock => {

        // Feature : Support structural group nesting natively per room layout block
        const sectionGroupItem = {
            linkId: resourceBlock.id || `group-${Math.random().toString(36).substr(2, 5)}`,
            text: resourceBlock.label || `${resourceBlock.resourceType} Section`,
            type: "group",
            repeats: resourceBlock.repeats || false,
            item: []
        };

        // Feature : Apply the FHIR itemControl extension to draw tables of fields ('gtable')
        if (resourceBlock.itemControl === 'gtable') {
            sectionGroupItem.extension = [{
                url: "http://hl7.org",
                valueCodeableConcept: {
                    coding: [{ system: "http://hl7.org", code: "gtable" }]
                }
            }];
        }

        resourceBlock.fields.forEach(field => {
            const fhirItem = {
                linkId: field.id || field.path, // Your path maps directly to the unique form item ID
                text: field.label,
                type: mapUiComponentToFhirType(field.uiComponent),
                repeats: field.uiComponent === 'MultiSelect' ? true : (field.repeats || false),
                required: field.required || false,
                // CRUCIAL SDC TASK: Embed the definition string enabling zero-code HAPI Server $extract mapping
                definition: `http://hl7.org/${resourceBlock.resourceType}#${field.path}`
            };

            if (field.description) {
                fhirItem.description = field.description;
            }

            // Carries scribe-training keywords (set via the designer's "Training the Form" step
            // and written back into the YAML) through to the compiled item, so reverse-mapping
            // keyword matching survives a fresh recompile instead of only living in memory.
            if (Array.isArray(field.keywords) && field.keywords.length > 0) {
                fhirItem.keywords = field.keywords;
            }

            if (field.uiComponent === 'Autocomplete' && field.valueSetUrl) {
                if (!fhirItem.extension) fhirItem.extension = [];

                // 1. Inject the explicit item-level target terminology server URL
                fhirItem.extension.push({
                    url: "http://hl7.org/fhir/StructureDefinition/terminology-server",
                    valueUrl: "https://clinicaltables.nlm.nih.gov/fhir/R4"
                });

                // 2. Inject the native NLM questionnaire-itemControl autocomplete metadata
                fhirItem.extension.push({
                    url: "http://hl7.org/fhir/StructureDefinition/questionnaire-itemControl",
                    valueCodeableConcept: {
                        coding: [{
                            system: "http://hl7.org/fhir/questionnaire-item-control",
                            code: "autocomplete",
                            display: "Auto-complete"
                        }],
                        text: "Auto-complete"
                    }
                });

                // 3. Bind the canonical answer valueset target path destination directly
                fhirItem.answerValueSet = field.valueSetUrl;
            }

            // Pre-populate hidden or admin elements natively using the initial parameter block
            if (field.uiComponent === 'Hidden' && field.defaultValue !== undefined) {
                fhirItem.initial = [{ valueString: String(field.defaultValue) }];
                // Add standard UI hiding context extension hints for frontend renders
                fhirItem.extension = [
                    {
                        url: "http://hl7.org",
                        valueBoolean: true
                    }
                ];
            }

            // Advanced Feature: Handle a selection list of multiple unit measurement values (Dropdown selector)
            if (field.unitChoices && Array.isArray(field.unitChoices)) {
                if (!fhirItem.extension) fhirItem.extension = [];
                field.unitChoices.forEach(unitCode => {
                    fhirItem.extension.push({
                        url: "http://hl7.org",
                        valueCoding: {
                            system: "http://unitsofmeasure.org",
                            code: unitCode,
                            display: unitCode
                        }
                    });
                });
            }
            // Feature 3: Fallback safely to a single fixed static unit text marker extension if provided
            else if (field.unit) {
                if (!fhirItem.extension) fhirItem.extension = [];
                fhirItem.extension.push({
                    url: "http://hl7.org",
                    valueCoding: {
                        system: "http://unitsofmeasure.org",
                        code: field.unit,
                        display: field.unit
                    }
                });
            }

            // Feature 7: Inject associated inline help text buttons into the view definition
            if (field.helpText) {
                if (!fhirItem.extension) fhirItem.extension = [];
                fhirItem.extension.push({
                    url: "http://hl7.org",
                    valueCodeableConcept: {
                        coding: [{ system: "http://hl7.org", code: "help" }]
                    }
                });
                // Append help sub-item display node sheet
                fhirItem.item = [{
                    linkId: `${field.path}-help-text`,
                    text: field.helpText,
                    type: "display"
                }];
            }
            // Feature 4: Handle large AJAX autocompletion links via answerValueSet target urls

            if (field.valueSetUrl) {
                fhirItem.answerValueSet = field.valueSetUrl;
            }

            // Feature 2: Append standard choice options to dropdown selectors if configured
            if (field.choices && !field.valueSetUrl) {
                fhirItem.answerOption = field.choices.map(choiceString =>
                    ({ valueString: choiceString }));
            }

            // Feature 8: Inject Skip Logic constraints using standard enableWhen structures
            if (field.skipLogic) {
                fhirItem.enableWhen = [{
                    question: field.skipLogic.sourceField,
                    operator: field.skipLogic.operator === 'exists' ? 'exists' : '=',
                    answerBoolean: field.skipLogic.operator === 'exists' ? true : undefined,
                    answerString: field.skipLogic.operator !== 'exists' ? field.skipLogic.value : undefined
                }];
            }

            sectionGroupItem.item.push(fhirItem);
        });
        fhirQuestionnaire.item.push(sectionGroupItem);
    });

    return { success: true, questionnaire: fhirQuestionnaire };
}
